OUT = os.path.dirname(os.path.abspath(__file__))


def main():
    os.makedirs(os.path.join(OUT, "protocols"), exist_ok=True)
    for d in IDEAS:
        p = gen.build(d)
        p["study_dir"] = "analysis/open-ideas-design-20261101/protocols"
        with open(os.path.join(OUT, "protocols", d["idea"] + ".json"), "w") as fh:
            json.dump(p, fh, indent=2)
            fh.write("\n")
    with open(os.path.join(OUT, "DESIGN.md"), "w") as fh:
        fh.write(gen.render_md(IDEAS).replace("2026-10-31", "2026-11-01"))
    print("wrote", len(IDEAS))


if __name__ == "__main__":
    main()
